class Solution {
  public int minOperations(int[] nums, int sum) {
    int INF = Integer.MAX_VALUE / 2, CAP = 2 * Math.max(sum, 500) + 5;
    int[] dp = new int[sum + 1];
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int x : nums) {
      int[] dist = new int[CAP + 1];
      java.util.Arrays.fill(dist, INF);
      java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
      dist[x] = 0;
      queue.add(x);
      while (!queue.isEmpty()) {
        int u = queue.poll();
        int[] nexts = {u * 2, u / 2};
        for (int v : nexts) {
          if (v >= 1 && v <= CAP && dist[v] == INF) {
            dist[v] = dist[u] + 1;
            queue.add(v);
          }
        }
      }
      int[] nd = dp.clone();
      for (int val = 1; val <= sum; val++) {
        if (dist[val] >= INF) continue;
        for (int s = sum; s >= val; s--) {
          if (dp[s - val] < INF) nd[s] = Math.min(nd[s], dp[s - val] + dist[val]);
        }
      }
      dp = nd;
    }
    return dp[sum] >= INF ? -1 : dp[sum];
  }
}
